contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(bytes32 digest, bytes32 r, bytes32 s) internal {
        vm.assume(!c.approvedLoggers(address(this)));
        bool obs;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool __r) { obs = __r; } catch { return; }
        assertTrue(!obs);
    }

    function testFuzz_run(bytes32 digest, bytes32 r, bytes32 s) public {
        _run(digest, r, s);
    }

    receive() external payable {}
}
